function updateHud(){if(!game)return;scoreEl.textContent=String(game.score).padStart(4,'0');healthEl.innerHTML=Array.from({length:game.player.maxHp},(_,i)=>`<i class="heart ${i<game.player.hp?'on':''}"></i>`).join('');waveEl.textContent=`WAVE ${String(Math.min(game.wave,5)).padStart(2,'0')} / 05`;}
function burst(x,y,color,n=9,speed=130){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),v=rand(speed*.25,speed);game.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),max:.65,r:rand(1,3),color});}}
function spawnEnemy(){
  const side=Math.floor(rand(0,4)), pad=24; let x,y;
  if(side===0){x=rand(0,W);y=-pad}else if(side===1){x=W+pad;y=rand(0,H)}else if(side===2){x=rand(0,W);y=H+pad}else{x=-pad;y=rand(0,H)}
  const roll=Math.random(), type=game.wave>=3&&roll<.22?'brute':game.wave>=2&&roll<.53?'swift':'drone';
  const spec=type==='brute'?{r:19,hp:3,speed:45,value:30,color:'#ff8a71'}:type==='swift'?{r:10,hp:1,speed:112,value:18,color:'#e6abff'}:{r:13,hp:1,speed:67,value:12,color:'#ffcf76'};
  game.enemies.push({x,y,vx:0,vy:0,...spec,type,phase:rand(0,6),flash:0});
}
function shoot(){const p=game.player,a=p.angle,speed=480;game.shots.push({x:p.x+Math.cos(a)*18,y:p.y+Math.sin(a)*18,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:1.15});p.fire=.17;}
function update(dt){
  const g=game,p=g.player;g.time+=dt;g.waveTime+=dt;g.spawnTimer-=dt;
  if(g.waveTime>21){if(g.wave>=5){end(true);return;}g.wave++;g.waveTime=0;g.spawnTimer=.75;g.floaters.push({x:W/2,y:90,text:`WAVE ${String(g.wave).padStart(2,'0')}`,life:1.7,color:'#8dffce'});}
  const limit=5+g.wave*2;if(g.spawnTimer<=0&&g.enemies.length<limit){spawnEnemy();g.spawnTimer=Math.max(.35,1.05-g.wave*.095)+rand(0,.35);}
  let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);
  dx+=touch.moveX;dy+=touch.moveY;const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}
  const accel=700;p.vx+=dx*accel*dt;p.vy+=dy*accel*dt;p.vx*=Math.pow(.001,dt);p.vy*=Math.pow(.001,dt);p.x=clamp(p.x+p.vx*dt,22,W-22);p.y=clamp(p.y+p.vy*dt,25,H-24);
  let aim=pointer.active?pointer:{x:p.x+1,y:p.y};p.angle=Math.atan2(aim.y-p.y,aim.x-p.x);
  p.fire-=dt;if((pointer.down||keys.has(' ')||touch.firing)&&p.fire<=0)shoot();p.invuln=Math.max(0,p.invuln-dt);
  for(const s of g.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;}g.shots=g.shots.filter(s=>s.life>0&&s.x>-30&&s.x<W+30&&s.y>-30&&s.y<H+30);
  for(const e of g.enemies){let vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy)||1;e.vx=vx/d*e.speed;e.vy=vy/d*e.speed;e.x+=e.vx*dt;e.y+=e.vy*dt;e.phase+=dt*3;e.flash=Math.max(0,e.flash-dt);}
  for(const s of g.shots){for(const e of g.enemies){if(e.hp>0&&Math.hypot(s.x-e.x,s.y-e.y)<e.r+4){e.hp--;s.life=0;e.flash=.09;burst(s.x,s.y,'#b4ffe1',3,60);if(e.hp<=0){g.score+=e.value;g.kills++;burst(e.x,e.y,e.color,12,150);if(Math.random()<.25)g.scrap.push({x:e.x,y:e.y,r:7,life:9,spin:rand(0,6)});}}}}
  g.enemies=g.enemies.filter(e=>e.hp>0);g.scrap=g.scrap.filter(s=>s.life>0);
  for(const s of g.scrap){s.life-=dt;s.spin+=dt*4;if(Math.hypot(s.x-p.x,s.y-p.y)<s.r+p.r+8){s.life=0;g.score+=5;if(p.hp<p.maxHp)p.hp++;g.floaters.push({x:p.x,y:p.y-20,text:'+5  +SHIELD',life:.8,color:'#8dffce'});burst(s.x,s.y,'#8dffce',8,100);}}
  for(const e of g.enemies){if(p.invuln<=0&&Math.hypot(p.x-e.x,p.y-e.y)<p.r+e.r-3){p.hp--;p.invuln=1.15;g.shake=8;burst(p.x,p.y,'#ff786e',15,180);e.hp=0;if(p.hp<=0){updateHud();end(false);return;}}}
  g.enemies=g.enemies.filter(e=>e.hp>0);
  for(const q of g.particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vx*=Math.pow(.08,dt);q.vy*=Math.pow(.08,dt);q.life-=dt;}g.particles=g.particles.filter(q=>q.life>0);
  for(const f of g.floaters){f.y-=18*dt;f.life-=dt;}g.floaters=g.floaters.filter(f=>f.life>0);g.shake=Math.max(0,g.shake-dt*28);updateHud();
}
const touch={moveX:0,moveY:0,firing:false};
const stick=document.getElementById('stick');let stickId=null;
stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e);});
stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e);});
function moveStick(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2),m=Math.hypot(x,y);touch.moveX=m>1?x/m:x;touch.moveY=m>1?y/m:y;}
function clearStick(e){if(e.pointerId===stickId){stickId=null;touch.moveX=touch.moveY=0;}}
stick.addEventListener('pointerup',clearStick);stick.addEventListener('pointercancel',clearStick);
const fireButton=document.getElementById('fire');fireButton.addEventListener('pointerdown',e=>{touch.firing=true;fireButton.setPointerCapture(e.pointerId);pointer.active=false;});fireButton.addEventListener('pointerup',()=>touch.firing=false);fireButton.addEventListener('pointercancel',()=>touch.firing=false);

