  const touch={moveX:0,moveY:0,firing:false};
  const stick=document.getElementById('stick');let stickId=null;
  stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e);});
  stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e);});
  function moveStick(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2),m=Math.hypot(x,y);touch.moveX=m>1?x/m:x;touch.moveY=m>1?y/m:y;}
  function clearStick(e){if(e.pointerId===stickId){stickId=null;touch.moveX=touch.moveY=0;}}
  stick.addEventListener('pointerup',clearStick);stick.addEventListener('pointercancel',clearStick);
  const fireButton=document.getElementById('fire');fireButton.addEventListener('pointerdown',e=>{touch.firing=true;fireButton.setPointerCapture(e.pointerId);pointer.active=false;});fireButton.addEventListener('pointerup',()=>touch.firing=false);fireButton.addEventListener('pointercancel',()=>touch.firing=false);
  function drawBackground(){
    ctx.clearRect(0,0,W,H); const v=ctx.createLinearGradient(0,0,0,H);v.addColorStop(0,'#051a22');v.addColorStop(1,'#030d14');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
    ctx.fillStyle='rgba(130,170,180,.08)';
    for(const s of game.stars){const px=(s.x+s.p*0.3)%W; const py=(s.y+game.time*9*s.s*0.3)%H; ctx.fillRect(px,py,s.s,s.s);}
    ctx.strokeStyle='rgba(120,204,182,.08)';ctx.lineWidth=1;for(let x=0;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  }
  function drawPlayer(){const p=game.player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle= p.invuln>0&&Math.floor(game.time*18)%2===0?'rgba(255,255,255,.35)':'#d7fff5';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-12,9);ctx.lineTo(-8,0);ctx.lineTo(-12,-9);ctx.closePath();ctx.fill();
    ctx.fillStyle='rgba(141,255,206,.96)';ctx.fillRect(-8,-2,14,4);ctx.restore();
    ctx.fillStyle='rgba(255,255,255,.72)';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+Math.cos(p.angle)*15,p.y+Math.sin(p.angle)*15);ctx.strokeStyle='rgba(141,255,206,.5)';ctx.lineWidth=2;ctx.stroke();}
  function drawShots(){for(const s of game.shots){ctx.fillStyle='rgba(255,255,255,.8)';ctx.fillRect(s.x-1.5,s.y-1.5,3,3);}}
  function drawEnemies(){for(const e of game.enemies){ctx.save();ctx.translate(e.x,e.y);ctx.strokeStyle='rgba(0,0,0,.25)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.stroke();ctx.fillStyle=e.flash>0?'#fff7f3':'e.color;ctx.beginPath();ctx.arc(0,0,e.r-2,0,Math.PI*2);ctx.fill();ctx.restore();}}
  function drawScrap(){for(const s of game.scrap){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.spin);ctx.fillStyle='rgba(141,255,206,.9)';ctx.fillRect(-4,-4,8,8);ctx.restore();}}
  function drawParticles(){for(const p of game.particles){ctx.fillStyle=p.color;ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillRect(p.x,p.y,p.r,p.r);ctx.globalAlpha=1;}}
  function drawFloaters(){for(const f of game.floaters){ctx.fillStyle=f.color;ctx.font='700 14px "DM Mono", monospace';ctx.textAlign='center';ctx.fillText(f.text, f.x, f.y);}}
  function render(){
    if(!game){ctx.clearRect(0,0,canvas.width,canvas.height);return;}
    ctx.save(); ctx.translate(Math.random()*game.shake-game.shake/2,Math.random()*game.shake-game.shake/2); drawBackground();
    drawParticles(); drawScrap(); drawShots(); drawEnemies(); drawPlayer(); drawFloaters(); ctx.restore();
  }
  let lastTime=0; function loop(ts){ if(!lastTime) lastTime=ts; const dt=Math.min((ts-lastTime)/1000, .033); lastTime=ts; if(game&&game.state==='play') update(dt); render(); requestAnimationFrame(loop); }
  requestAnimationFrame(loop);
  function init(){
    document.getElementById('title').innerHTML='KEEP THE<br><em>LIGHT ALIVE.</em>';
    document.getElementById('message').textContent='The dark is closing in. Hold the line, collect scrap, and make it through five waves.';
    document.getElementById('eyebrow').textContent='LAST LIGHT PROTOCOL';
    document.getElementById('action').textContent='BEGIN RUN  →';
    document.getElementById('foot').textContent='OR USE ARROW KEYS · SPACE TO FIRE';
    toggleOverlay(true);
    updateHud();
    game = makeGame();
    game.state='ready';
  }
  init();
  window.addEventListener('blur',()=>{if(game&&game.state==='play')pause();});
  window.addEventListener('pointerdown',e=>{if(game&&game.state==='ready'&&e.target===canvas){start();}});
  window.addEventListener('pointermove',e=>{if(game&&game.state==='ready'){pointer.active=true;Object.assign(pointer,toGame(e.clientX,e.clientY));}});
  document.getElementById('fire').addEventListener('touchstart',e=>{e.preventDefault();touch.firing=true;}, {passive:false});
  document.getElementById('fire').addEventListener('touchend',()=>touch.firing=false);
  document.getElementById('fire').addEventListener('touchcancel',()=>touch.firing=false);
  document.body.addEventListener('contextmenu',e=>e.preventDefault());
})();
</script>
</body>
